add_action( 'woocommerce_single_product_summary', 'perfectpixel_custom_field_on_product_page', 25 );

function perfectpixel_custom_field_on_product_page() {
	$value = get_post_meta( get_the_ID(), sanitize_key( '{{product_field_key}}' ), true );
	if ( is_array( $value ) ) {
		$value = implode( ', ', array_map( 'strval', array_filter( $value, 'is_scalar' ) ) );
	}
	if ( '' === trim( (string) $value ) ) {
		return;
	}
	$label = trim( '{{product_field_label}}' );
	echo '<p class="perfectpixel-product-field">' . ( '' !== $label ? '<strong>' . esc_html( $label ) . '</strong> ' : '' ) . esc_html( $value ) . '</p>';
}
